 {page==='audit'&&<Table header={<Header variant="h2" description="Latest 300 local events. No prompt bodies, credentials, or chain of thought in audit records.">Audit events</Header>} items={audit} columnDefinitions={[{id:'time',header:'Time',cell:a=>new Date(a.created*1000).toLocaleString()},{id:'actor',header:'Actor',cell:a=>a.actor},{id:'action',header:'Action',cell:a=>pretty(a.action)},{id:'resource',header:'Resource',cell:a=><span className="digest">{a.resource}</span>},{id:'detail',header:'Decision detail',cell:a=>a.detail}]}/>}
